-- Add latest production records without replacing the existing workspace.
CREATE TABLE pm.hourly_records (
 owner_id UUID NOT NULL DEFAULT auth.uid(),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY,
 id TEXT NOT NULL,project_id TEXT NOT NULL,data_json TEXT NOT NULL,recorded_at TEXT NOT NULL,revision INTEGER NOT NULL,
 PRIMARY KEY(owner_id,id),FOREIGN KEY(owner_id,project_id) REFERENCES pm.projects(owner_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE pm.sample_preparation_records (
 owner_id UUID NOT NULL DEFAULT auth.uid(),rowid BIGINT GENERATED BY DEFAULT AS IDENTITY,
 id TEXT NOT NULL,project_id TEXT NOT NULL,sheet_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),data_json TEXT NOT NULL,recorded_at TEXT NOT NULL,revision INTEGER NOT NULL,
 PRIMARY KEY(owner_id,id),UNIQUE(owner_id,project_id,sheet_id,version),FOREIGN KEY(owner_id,project_id) REFERENCES pm.projects(owner_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX hourly_project ON pm.hourly_records(owner_id,project_id,revision);
CREATE INDEX sample_preparation_project ON pm.sample_preparation_records(owner_id,project_id,revision);
ALTER TABLE pm.hourly_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE pm.sample_preparation_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_rows ON pm.hourly_records TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE POLICY own_rows ON pm.sample_preparation_records TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON pm.hourly_records,pm.sample_preparation_records TO authenticated;
GRANT USAGE,SELECT ON SEQUENCE pm.hourly_records_rowid_seq,pm.sample_preparation_records_rowid_seq TO authenticated;
-- Forward preserved production rows from the exact recovery archive, if present.
INSERT INTO pm.hourly_records(owner_id,id,project_id,data_json,recorded_at,revision)
 SELECT b.owner_id,j->>'id',j->>'project_id',j->>'data_json',j->>'recorded_at',(j->>'revision')::integer
 FROM pm.backup_recovery_rows r JOIN pm.backup_recovery b ON b.id=r.recovery_id CROSS JOIN LATERAL (SELECT r.row_text::jsonb AS j) parsed
 WHERE b.state='committed' AND r.table_name='hourly_records' ON CONFLICT DO NOTHING;
INSERT INTO pm.sample_preparation_records(owner_id,id,project_id,sheet_id,version,data_json,recorded_at,revision)
 SELECT b.owner_id,j->>'id',j->>'project_id',j->>'sheet_id',(j->>'version')::integer,j->>'data_json',j->>'recorded_at',(j->>'revision')::integer
 FROM pm.backup_recovery_rows r JOIN pm.backup_recovery b ON b.id=r.recovery_id CROSS JOIN LATERAL (SELECT r.row_text::jsonb AS j) parsed
 WHERE b.state='committed' AND r.table_name='sample_preparation_records' ON CONFLICT DO NOTHING;
CREATE FUNCTION public.pm_public_production_read(operation TEXT,project_id TEXT DEFAULT '')
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE owner UUID; result JSONB; snapshot_list JSONB;
BEGIN
 SELECT p.owner_id INTO owner FROM pm.publication p WHERE p.singleton=true;
 IF owner IS NULL THEN RAISE EXCEPTION 'No public workspace configured.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pm.projects p WHERE p.owner_id=owner AND p.id=project_id) THEN RAISE EXCEPTION 'Unknown project.'; END IF;
 IF operation='hourly' THEN
  SELECT coalesce(jsonb_agg((r.data_json::jsonb-'sourceId')||jsonb_build_object('id',r.id,'recordedAt',r.recorded_at,'recordRevision',r.revision) ORDER BY r.revision,r.id),'[]'::jsonb) INTO result FROM pm.hourly_records r WHERE r.owner_id=owner AND r.project_id=pm_public_production_read.project_id;
 ELSIF operation='sample-preparation' THEN
  SELECT coalesce(jsonb_agg(
   (SELECT jsonb_object_agg(k,v) FROM jsonb_each(j) x(k,v) WHERE k IN ('id','partId','runName','templateVersion','version','profile','sampleDate','preparationDate','sampleQuantity','memo'))
   ||jsonb_build_object('answers',coalesce((SELECT jsonb_agg(jsonb_build_object('questionId',a->'questionId','status',a->'status','note',a->'note')) FROM jsonb_array_elements(j->'answers') a),'[]'::jsonb))),'[]'::jsonb) INTO result
  FROM (SELECT DISTINCT ON(r.sheet_id) r.data_json::jsonb AS j FROM pm.sample_preparation_records r WHERE r.owner_id=owner AND r.project_id=pm_public_production_read.project_id ORDER BY r.sheet_id,r.version DESC,r.revision DESC,r.id) latest;
 ELSIF operation='progress' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'capturedAt',s.captured_at,'createdAt',s.created_at,'unit',CASE WHEN s.sheet LIKE 'Progress · %' THEN substr(s.sheet,12) ELSE 'pcs' END) ORDER BY s.captured_at,s.created_at),'[]'::jsonb) INTO snapshot_list FROM (SELECT * FROM pm.wip_snapshots s WHERE s.owner_id=owner AND s.project_id=pm_public_production_read.project_id ORDER BY s.captured_at,s.created_at LIMIT 2000) s;
  SELECT jsonb_build_object('snapshots',snapshot_list,'rows',coalesce(jsonb_agg(snap||jsonb_build_object('snapshotId',c.snapshot_id,'partId',c.part_id,'stepId',c.step_id,'code',c.product_code,'partName',c.part_label,'stage',c.stage_label,'row',c.source_row,'column',c.source_column,'quantity',c.quantity) ORDER BY snap->>'capturedAt',snap->>'createdAt'),'[]'::jsonb)) INTO result FROM jsonb_array_elements(snapshot_list) snap JOIN pm.wip_counts c ON c.snapshot_id=snap->>'id' AND c.owner_id=owner WHERE c.part_id IS NOT NULL AND c.step_id IS NOT NULL;
 ELSE RAISE EXCEPTION 'Unsupported public operation.';
 END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.pm_public_production_read(TEXT,TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.pm_public_production_read(TEXT,TEXT) TO anon,authenticated;
NOTIFY pgrst,'reload schema';
